    // Shared across copies of this ref struct; a readonly struct held by a `using` variable cannot
    // hold mutable state itself.
    private readonly State _state;

    internal FileScope(SourceWriter writer)
    {
        _writer = writer;
        _state = new State();
    }

    /// <summary>Writes <c>using <paramref name="namespaceName"/>;</c>.</summary>
    public void Using(string namespaceName)
    {
        _writer.WriteLine($"using {namespaceName};");
        _state.NeedsBlankLine = true;
    }

    /// <summary>
    /// Writes <c>namespace <paramref name="name"/></c> and opens its block; disposing the returned scope
    /// closes the block. A blank line separates it from preceding usings or namespaces. There is no
    /// global-namespace scope: write global-namespace code directly on the file scope's writer.
