            _writer.WriteLine();
        }

        _state.NeedsBlankLine = true;
        _writer.WriteLine($"namespace {name}");

        return new NamespaceScope(_writer, _writer.Block());
    }

    /// <summary>
    /// Writes <paramref name="type"/>'s partial declaration (containing types included) at file level, for
    /// the global namespace, and returns the scope of its innermost block. A blank line separates it from
    /// preceding usings, namespaces or types.
    /// <paramref name="type"/>'s <see cref="TypeModel.Namespace"/> is ignored: the enclosing
    /// scope is the source of truth for the namespace.
    /// </summary>
    /// <exception cref="ArgumentException"><paramref name="type"/> is file-local.</exception>
    public TypeScope Type(TypeModel type)
